import Foundation

public struct EmojiItem: Codable, Equatable {
    public let emoji: String
    public let group: Int
    public let skins: [String]?
    enum CodingKeys: String, CodingKey { case emoji = "e", group = "g", skins = "s" }

    /// The emoji in the chosen skin tone (1–5), or the default yellow when tone is 0 or unsupported.
    public func toned(_ tone: Int) -> String {
        guard tone > 0, let skins, skins.indices.contains(tone - 1) else { return emoji }
        return skins[tone - 1]
    }
}

/// The full emoji set (Unicode Emoji 15.0, generated by Scripts/build_emoji.py from emojibase-data)
/// with search keywords in the languages that have them.
public final class EmojiCatalog {
    public static let shared = EmojiCatalog()

    public static let groups: [(id: Int, icon: String, name: String)] = [
        (0, "😀", "Smileys"), (1, "👋", "People"), (3, "🐻", "Animals & nature"), (4, "🍔", "Food & drink"),
        (5, "🚗", "Travel & places"), (6, "⚽", "Activities"), (7, "💡", "Objects"), (8, "❤️", "Symbols"), (9, "🏳️", "Flags")
    ]

    public private(set) lazy var items: [EmojiItem] = {
        guard let url = LanguageCatalog.resourceBundle.url(forResource: "emoji", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return [] }
        return (try? JSONDecoder().decode([EmojiItem].self, from: data)) ?? []
    }()
    private lazy var byEmoji: [String: EmojiItem] = Dictionary(items.map { ($0.emoji, $0) }, uniquingKeysWith: { first, _ in first })
    private var keywords: [String: [(String, String)]] = [:]
    private let lock = NSLock()

    public init() {}

    public func items(in group: Int) -> [EmojiItem] { items.filter { $0.group == group } }
    public func item(for emoji: String) -> EmojiItem? { byEmoji[emoji] ?? items.first { $0.skins?.contains(emoji) == true } }

    /// Emoji whose name or keywords match every word of the query, best matches first.
    /// English keywords are always searched as well as the person's languages.
    public func search(_ query: String, languages: [String], limit: Int = 60) -> [EmojiItem] {
        let terms = query.lowercased().split(whereSeparator: \.isWhitespace).map(String.init)
        guard !terms.isEmpty else { return [] }
        var scores: [String: Int] = [:]
        for code in Array(Set(languages + ["en"])) {
            for (emoji, words) in keywordList(code) {
                guard terms.allSatisfy({ words.contains($0) }) else { continue }
                // Whole-word and leading matches rank above matches inside other words.
                let padded = " " + words + " "
                let score = terms.reduce(0) { total, term in
                    total + (padded.contains(" \(term) ") ? 3 : (padded.contains(" \(term)") ? 2 : 1))
                }
                scores[emoji] = max(scores[emoji] ?? 0, score)
            }
        }
        let order = Dictionary(items.enumerated().map { ($1.emoji, $0) }, uniquingKeysWith: { first, _ in first })
        return scores.keys.sorted { scores[$0]! == scores[$1]! ? (order[$0] ?? 0) < (order[$1] ?? 0) : scores[$0]! > scores[$1]! }
            .prefix(limit).compactMap { byEmoji[$0] }
    }

    private func keywordList(_ code: String) -> [(String, String)] {
        lock.lock(); defer { lock.unlock() }
        if let cached = keywords[code] { return cached }
        var list: [(String, String)] = []
        if let url = LanguageCatalog.resourceBundle.url(forResource: "emojikw-\(code)", withExtension: "txt"),
           let text = try? String(contentsOf: url, encoding: .utf8) {
            for line in text.split(separator: "\n") {
                guard let tab = line.firstIndex(of: "\t") else { continue }
                list.append((String(line[..<tab]), String(line[line.index(after: tab)...])))
            }
        }
        keywords[code] = list
        return list
    }
}
